// Complete Surveyed Real-World Railway Track Network (844 segments)
// Extracted directly from OpenRailwayMap surveyed geospatial data

export interface CanvasPoint { x: number; y: number; }
export interface GpsPoint { lat: number; lng: number; }

export interface NetworkTrackSegment {
  id: string;
  name: string;
  category: 'main' | 'chetpet_branch' | 'crossover' | 'loop';
  canvasPoints: CanvasPoint[];
}

export const CANVAS_BOUNDS = {
  width: 5400,
  height: 3200,
  minLat: 12.675,
  maxLat: 13.115,
  minLng: 79.965,
  maxLng: 80.305
};

export const projectGpsToCanvas = (lat: number, lng: number): CanvasPoint => {
  const normX = (lng - CANVAS_BOUNDS.minLng) / (CANVAS_BOUNDS.maxLng - CANVAS_BOUNDS.minLng);
  const normY = 1.0 - (lat - CANVAS_BOUNDS.minLat) / (CANVAS_BOUNDS.maxLat - CANVAS_BOUNDS.minLat);
  return {
    x: Math.round(250 + normX * (CANVAS_BOUNDS.width - 500)),
    y: Math.round(200 + normY * (CANVAS_BOUNDS.height - 400))
  };
};

